from research_helpers import *
N=ev('https://www.sec.gov/Archives/edgar/data/1467154/000146715423000029/novn-20221231.htm','Novan issuer identifies SB204, SB206, SB208, SB414, SB019 and Nitricil platform. Separate formulations are distinct programmes despite shared nitric-oxide chemistry.')
C=ev('https://www.sec.gov/Archives/edgar/data/1467154/000146715423000047/novn-20230331.htm','Issuer describes EPI Health commercial portfolio and exact roles: MC2 owns Wynzora; Novan commercial partner, not original developer. Historical source does not establish current Novan marketing.')
S=ev('https://www.sec.gov/Archives/edgar/data/1467154/000146715423000109/novn-20230927.htm','Issuer confirms completed September27 2023 Ligand disposition of Nitricil-related assets. Not all EPI products assumed transferred identically.')
L=ev('https://www.sec.gov/Archives/edgar/data/886163/000088616324000009/lgnd-20231231.htm','Buyer confirms berdazimer, Nitricil-related assets and one commercial-stage asset purchased September27 2023.')
Z=ev('https://pelthos.com/pelthos-therapeutics-launches-zelsuvmi-berdazimer-topical-gel-10-3-the-first-and-only-fda-approved-at-home-treatment-for-molluscum-contagiosum/','Successor confirms commercial ZELSUVMI launch. Novan linked for historical development, not current sales.')
F=ev('https://www.fda.gov/drugs/drug-approvals-and-databases/drug-trials-snapshots-zelsuvmi','FDA confirms ZELSUVMI approval January5 2024.')
ps=[p('ZELSUVMI','Berdazimer 10.3% topical gel for molluscum contagiosum.',Z,'commercial',aliases=['SB206'],attributes={'generic_name':'berdazimer','relationship_scope':'historical_Novan_development; transferred_2023-09-27'},evidence=[N,S,L,Z,F])]
for n,d in [('SB204','Acne-specific nitric-oxide topical formulation.'),('SB208','Antifungal nitric-oxide topical formulation.'),('SB414','Inflammatory skin-disease formulation.'),('SB019','Historical respiratory anti-infective programme.')]:ps.append(p(n,d,N,attributes={'current_development_status':'requires_successor_confirmation'},evidence=[N,S,L]))
ps.append(p('Nitricil','Nitric-oxide release technology platform.',N,typ='technology',evidence=[N,S,L]))
for n,d in [('WYNZORA','Calcipotriene/betamethasone cream.'),('RHOFADE','Oxymetazoline cream.'),('MINOLIRA','Biphasic minocycline tablets.'),('CLODERM','Clocortolone cream.'),('SITAVIG','Acyclovir buccal tablets.'),('NUVAIL','Poly-ureaurethane nail solution.')]:ps.append(p(n,d,C,roles=['commercial_partner'],typ='product',attributes={'relationship_scope':'historical_EPI_Health_commercial_portfolio','current_Novan_relationship':'unverified_after_bankruptcy'}))
A=ev('https://www.sec.gov/Archives/edgar/data/1607549/000147793219003830/appb_10k.htm','Applied BioSciences issuer describes CBD consumer/pet wellness brands and testing services; no named approved cannabinoid therapeutic established.')
E=ev('https://www.sec.gov/enforcement-litigation/litigation-releases/lr-24819','SEC alleges 2020 COVID-test shipping and authorization claims misleading. Those marketing claims not accepted as verified commercial diagnostic product evidence.')
cs=[company('NOVAN INC. DL-0001',ps,[N,C,S,L,Z,F],'Nitricil/SB programmes and six historical EPI commercial products captured. ZELSUVMI current successor commercialization distinguished from Novan historical development. Other SB lifecycle, earlier candidates and EPI product-specific disposition dates require followup.'),company('Applied Biosciences Corp',[],[A,E],'Historical CBD wellness brands and analytical services reviewed; no exact qualifying therapeutic/research-tool product established. COVID-test marketing claims contradicted by SEC allegations and not used to fabricate an approved diagnostic record. Named therapeutic-development assets and exact legacy product identities require further research.')]
(out/'batch-0054.json').write_text(json.dumps({'companies':cs},indent=2));print(len(ps))
